import { describe, expect, it } from 'vitest';
import {
  DEFAULT_STYLE,
  MEASURED_AT,
  STYLE_IDS,
  STYLE_PROFILES,
  styleProfile,
  type Histogram,
  type StyleProfile,
} from './styleProfiles';

// These guard the analyser's output, not the loader. The profiles are
// regenerated by a Python tool outside the build, so a bad run would otherwise
// reach the generator silently — which is exactly what happened once, when a
// shadowed variable made the interval histogram report pitch classes and
// claimed 58% of lead playing was wide leaps.

const ALL = Object.entries(STYLE_PROFILES);

function sums(histogram: Histogram): number {
  return Object.values(histogram).reduce((total, share) => total + share, 0);
}

describe('style profiles', () => {
  it('ships the pooled profile and at least four styles', () => {
    expect(STYLE_PROFILES[DEFAULT_STYLE]).toBeDefined();
    expect(STYLE_IDS.length).toBeGreaterThanOrEqual(4);
    expect(STYLE_IDS).not.toContain('all');
  });

  it('was measured at a readable time', () => {
    expect(Number.isNaN(Date.parse(MEASURED_AT))).toBe(false);
  });

  it('throws on an unknown style rather than returning undefined', () => {
    expect(() => styleProfile('jazz-fusion')).toThrow(/Unknown style/);
    expect(styleProfile()).toBe(STYLE_PROFILES[DEFAULT_STYLE]);
  });

  it.each(ALL)('%s was measured from enough playing to mean something', (_id, profile) => {
    expect(profile.passages).toBeGreaterThan(0);
    expect(profile.notes).toBeGreaterThanOrEqual(100);
    expect(profile.notesPerBar).toBeGreaterThan(1);
  });

  it.each(ALL)('%s reports every rate as a share', (_id, profile: StyleProfile) => {
    const rates = [
      profile.intervals.repeatRate,
      profile.intervals.stepwiseRate,
      profile.intervals.leapRate,
      profile.bends.rate,
      profile.strings.topThreeShare,
      profile.strings.sameStringRate,
      profile.tonality.coreFiveShare,
      profile.tonality.chromaticRate,
      profile.phraseEnds.onCoreFive,
      profile.rhythm.dominantShare,
      ...Object.values(profile.technique),
    ];
    for (const rate of rates) {
      expect(rate).toBeGreaterThanOrEqual(0);
      expect(rate).toBeLessThanOrEqual(1);
    }
  });

  it.each(ALL)('%s keeps its interval classes disjoint', (_id, profile) => {
    // repeat (0), stepwise (1-3) and leap (5+) cannot overlap, so together
    // they can never exceed everything. This is the check that would have
    // caught the shadowed-counter bug.
    const { repeatRate, stepwiseRate, leapRate } = profile.intervals;
    expect(repeatRate + stepwiseRate + leapRate).toBeLessThanOrEqual(1.001);
  });

  it.each(ALL)('%s has histograms that sum to one', (_id, profile) => {
    for (const histogram of [
      profile.intervals.histogram,
      profile.rhythm.histogram,
      profile.strings.distribution,
    ]) {
      expect(sums(histogram)).toBeCloseTo(1, 1);
    }
  });

  it.each(ALL)('%s describes intervals in semitones, not pitch classes', (_id, profile) => {
    // Every key is a semitone distance, capped at 12 ("an octave or more").
    const keys = Object.keys(profile.intervals.histogram).map(Number);
    expect(keys.every((k) => Number.isInteger(k) && k >= 0 && k <= 12)).toBe(true);
    // A lead line is mostly small steps. Anything near half of all motion
    // being a leap means the measurement, not the music, is wrong.
    expect(profile.intervals.leapRate).toBeLessThan(0.5);
    expect(profile.intervals.stepwiseRate).toBeGreaterThan(0.15);
  });

  it.each(ALL)('%s stays on the fretboard', (_id, profile) => {
    expect(profile.position.lowFret).toBeGreaterThanOrEqual(0);
    expect(profile.position.highFret).toBeLessThanOrEqual(24);
    expect(profile.hand.medianSpan).toBeLessThanOrEqual(profile.hand.p90Span);
    expect(profile.hand.p90Span).toBeLessThanOrEqual(profile.hand.maxSpan);
    expect(Object.keys(profile.strings.distribution).every((s) => +s >= 1 && +s <= 7)).toBe(true);
  });

  it.each(ALL)('%s turns direction like a player, not a scale run', (_id, profile) => {
    // Measured range across the sample is 1.66-2.19. A generator walking a
    // scale in one direction scores 4+, which is what this guards against.
    expect(profile.contour.notesPerReversal).toBeGreaterThan(1);
    expect(profile.contour.notesPerReversal).toBeLessThan(4);
    expect(profile.contour.maxRun).toBeGreaterThanOrEqual(profile.contour.medianRun);
  });

  it.each(ALL)('%s reports bend sizes only where there were bends', (_id, profile) => {
    if (profile.bends.rate === 0) {
      expect(profile.bends.medianSemitones).toBeNull();
    } else {
      expect(profile.bends.medianSemitones).toBeGreaterThan(0);
      expect(profile.bends.medianSemitones).toBeLessThanOrEqual(4);
    }
  });

  it('distinguishes the styles it claims to distinguish', () => {
    // If every profile were the same there would be no point tagging them.
    // Metal sits higher up the neck than classic rock, and grunge leans on a
    // five-note core harder than metal does.
    expect(STYLE_PROFILES.metal.position.medianFret)
      .toBeGreaterThan(STYLE_PROFILES['classic-rock'].position.medianFret);
    expect(STYLE_PROFILES.grunge.tonality.coreFiveShare)
      .toBeGreaterThan(STYLE_PROFILES.metal.tonality.coreFiveShare);
  });

  it('measures the repeated notes the generator currently never produces', () => {
    // The gap this whole exercise exists to close: real playing repeats a note
    // about a fifth of the time; the planner forces a move on every step.
    expect(STYLE_PROFILES.all.intervals.repeatRate).toBeGreaterThan(0.1);
  });
});
